  "localModels.managed.autoUpdate": { type: "boolean", description: "When true, managed-mode start (TUI auto-start / `s`, CLI `models start`) checks GitHub Releases and replaces the llama.cpp zip if a newer tag (or a stale Windows variant) is available. Default `true` since config v41. Older files stored an unused `false` default — those migrate to `true`. Set `false` to pin the installed backend." },
  "localModels.managed.stopOnExit": { type: "boolean", description: "Stop the managed chat daemon when the last CLI session exits. `true` (default) — closing the terminal frees the RAM/VRAM the model was holding; a second live session keeps the daemon up (see `session-registry.ts`). `false` — keep the model warm between sessions; the operator stops it via `atomic-agent models stop`." },
  "localModels.managed.autoRestart": { type: "boolean", description: "Bring the managed chat daemon back by itself when it dies (or, from the wedge watchdog, stops answering) while this TUI owns it. `true` (default): a crashed or killed llama-server is restarted within a few seconds and a parked turn resumes on it; three deaths within a minute of their start stop the retries and name the fault." },
  "localModels.managed.promptDiskCache": { type: "boolean", description: "Keep the chat daemon's prompt cache on disk between runs (ATO-456). `true`: the managed server starts with `--slot-save-path`, the cache of every idle slot is saved before a managed stop and the newest saves are loaded back after the next start, so a long conversation continues without the model reading it all again." },
  "localModels.managed.device": { type: "string", description: "Compute-device preference for the managed llama.cpp daemon: - `\"auto\"` (default) — enumerate via `llama-server --list-devices` at start and pick the best discrete GPU; CPU fallback when none. - a concrete backend device id (e.g. `\"Vulkan0\"`) — pin offload to that device. - `\"cpu\"` — force CPU-only (`-ngl 0`)." },
  "localModels.managed.backendVariant": { type: "'auto' | 'cpu' | 'vulkan' | 'cuda-12.4' | 'cuda-13.3'", description: "Which llama.cpp build (release zip) the managed backend installs. Windows-only — every other platform, Linux arm64 included, publishes a single asset, so there is nothing for the preference to choose between and it is ignored there." },
  "localModels.managed.coreBackendVariant": { type: "'auto' | 'cpu'", description: "Which build Atomic Core installs on Windows x64 (the `atomic-core` engine; `backendVariant` above is the llama-server engine's). - `\"auto\"` (default) — Core's recommendation for this hardware. - `\"cpu\"` — Core's CPU build." },
  "localModels.managed.contextSize": { type: "number", description: "llama-server context window (`--ctx-size`) for the managed chat daemon." },
  "localModels.managed.tensorSplit": { type: "number[]", description: "Multi-GPU tensor split for the managed chat daemon. Empty (the default) keeps the single-device behavior: `device` auto-picks the best GPU and pins offload there. Two or more non-negative ratios (at least one positive, e.g." },
  "localModels.managed.parallel": { type: "number | 'auto'", description: "llama-server request slots (`--parallel`) for the managed chat daemon: `\"auto\"` (the default since config v63) or a pinned 1..8." },
  "localModels.managed.swaFull": { type: "'off' | 'auto' | 'on'", description: "`--swa-full` for a sliding-window model (Gemma 4 and kin): keep the whole context in the sliding layers so a partially matching prompt reuses its matching prefix instead of re-reading everything — at a several-fold KV cost for those layers. - `\"auto\"` (default) — on when the full-SWA KV estimate fits the launch's memory budget (see `swa-full.ts`), else off." },
  "localModels.embeddings.enabled": { type: "boolean", description: "Run a second managed server for embeddings, next to the chat model. Default `false`: no embedding server and keyword-only memory recall." },
