  "localModels.customModels": { type: "LocalModelDef[]", description: "GGUF models the operator added from an arbitrary Hugging Face repo. Each entry is a whole `LocalModelDef` with a `custom-` prefixed id; `loadConfig()` publishes them to the catalog registry so curated and added models resolve through one lookup. Older files inherit `[]`." },
  "localModels.managed.loraAdapters": { type: "Record<string, LoraAdapter>", description: "LoRA adapters for the managed chat server, keyed by local model id (ATO-1106): `{ \"<modelId>\": { \"path\": \"/abs/adapter.gguf\", \"scale\": 0.8 } }`. The adapter of the model being launched is passed as `--lora` (or `--lora-scaled` when `scale` is not 1); a missing file fails that launch with its path.", optional: true },
  "localModels.managed.loraAdapters.*.path": { type: "string", description: "Absolute path to the adapter's `.gguf` file.", optional: true },
