  "agent.task.maxResumes": { type: "number", description: "Resumes after the agent died under a task (crash or kill) before the task is failed instead: the guard against a task that takes the agent down every time. `0` fails it at the first such interruption." },
  "agent.task.maxCostUsd": { type: "number", description: "Spend ceiling for one task, in USD, estimated from each completion's usage and the model's prices (prompt-cache aware). Reached, the task ends the same graceful way as the time ceiling. `0` means no cap. Unpriced models (a local model) count as $0, so this never stops local work. Default `0`." },
  "agent.task.replanEveryNSteps": { type: "number", description: "Ask the model to review and resend its live plan (`plan.update`) every this many steps of a long task (ATO-609). The request joins the next step's notice, so it costs no extra model call. `0` (the default) is off. Additive and unversioned: an older file has no field and never re-plans." },
  "agent.goal.maxTokens": { type: "number", description: "Token budget a new goal starts with: prompt plus completion tokens of all its rounds, as the provider reports them. `0` means no cap (rounds, time and money still bound a goal). `/goal tokens` changes it for one goal. Default `0`." },
