  "web.search.fallback": { type: "WebSearchProviderName[]", description: "Ordered fallback providers tried (after the primary) when a search is blocked / empty / throws. Default `[\"duckduckgo\"]` — DuckDuckGo's keyless HTML endpoint, which also takes over from a keyless Exa primary that hit its free limit." },
