  "web.fetch.timeoutMs": { type: "number", description: "Overall per-attempt budget in milliseconds, passed to curl `--max-time`. Kept at the historical 30_000 so unconfigured installs behave exactly as before. A per-call `timeoutMs` tool argument overrides it." },
  "web.fetch.connectTimeoutMs": { type: "number", description: "TCP/TLS connect budget in milliseconds, passed to curl `--connect-timeout`. Much smaller than `timeoutMs` because a host that has not completed a handshake in 10s is almost never merely slow — it is firewalled, dead, or blackholing packets, and waiting the full overall budget for it is pure loss." },
  "web.fetch.maxRetries": { type: "number", description: "Extra attempts after the first for retryable failures (429/502/503/504 and curl exit 28 \"operation timed out\"). `0` disables retrying. Deliberately small: `os.web.fetch` is GET-only, so retries are always safe, but each one spends task budget." },
  "web.fetch.retryBaseDelayMs": { type: "number", description: "Base delay in milliseconds for exponential backoff between retries (attempt N waits `retryBaseDelayMs * 2^(N-1)`). A server-sent `Retry-After` header wins over the computed delay when it is shorter than the cap." },
  "web.fetch.retryMaxDelayMs": { type: "number", description: "Upper bound in milliseconds on any single backoff wait, including one derived from `Retry-After`. Stops a hostile or overloaded origin from parking the agent for minutes on a header value." },
  "web.fetch.extractor": { type: "'readability' | 'defuddle'", description: "Main-content extractor tried first on an HTML page (ATO-698). Default `\"readability\"` (Mozilla Readability, as before). `\"defuddle\"` runs Defuddle first, which keeps code blocks, math and tables in the markdown, and falls back to Readability when it finds nothing. Off by default until it has been compared on real pages." },
  "web.fetch.renderWithBrowser": { type: "boolean", description: "Step 2 of the page-read ladder (ATO-968): when curl gets a bot-protection challenge, render the page in the agent's own browser and extract from that. Default `true`. Needs `browser.enabled`; never used with `browser.connect: \"user-chrome\"` (the user's signed-in Chrome), and the browser domain lists apply." },
  "web.fetch.jinaReader": { type: "boolean", description: "Step 3: Jina Reader without a key (rate-limited by Jina) when the page is still walled. Default `false`: it sends the URL to Jina. A key in `jinaApiKeyEnv` turns Jina on by itself." },
  "web.fetch.jinaApiKeyEnv": { type: "string", description: "Environment variable holding a Jina Reader key. Default `\"JINA_API_KEY\"`." },
  "web.fetch.firecrawlApiKeyEnv": { type: "string", description: "Environment variable holding a Firecrawl key; Firecrawl runs after Jina only when it is set. Default `\"FIRECRAWL_API_KEY\"`." },
  "web.crawl.minDelayMs": { type: "number", description: "Smallest gap between two requests to one host, in milliseconds. A robots.txt `Crawl-delay` that asks for more wins, up to 30 seconds. Default `1000` (one request a second)." },
  "web.crawl.maxPages": { type: "number", description: "Hard cap on pages one crawl reads. A call may ask for fewer. Default `50`." },
  "web.crawl.maxDepth": { type: "number", description: "Hard cap on link depth from the start page. Default `2`." },
  "web.crawl.respectRobots": { type: "boolean", description: "Obey robots.txt. Default `true`. Turning it off for every site is a blunt tool; `robotsExemptHosts` is the way for your own sites." },
  "web.crawl.robotsExemptHosts": { type: "string[]", description: "Hosts whose robots.txt is not applied (your own sites, a staging server). Exact host names, a leading `*.` matches subdomains. Default empty. The rate limit still applies to them." },
  "web.crawl.cacheTtlMinutes": { type: "number", description: "Minutes a fetched page or robots.txt is reused by later crawls. Zero disables. Default `15`." },
  "projects.roots": { type: "string[]", description: "Folders whose direct children are your projects; the agent matches project names against them. Empty: nothing is scanned." },
  "projects.constraints": { type: "Record<string, ProjectConstraintEntry>", description: "Absolute folder → which providers may receive a session's content while it works in or under that folder, and which egress its tools may use. Empty: nothing is constrained.", optional: true },
  "projects.constraints.*.allowedProviders": { type: "string[]", description: "Provider ids that may receive a request carrying content of a session working in or under this folder. An empty list lets no provider serve it.", optional: true },
  "projects.constraints.*.allowedEgress": { type: "string[]", description: "Egress classes the folder's tools may use to send content off the machine (`web`, `http`, `browser`, `github`, `git`, `channels`, `mail`, `composio`, `serve`, `mcp:<server>`). Absent or empty: none.", optional: true },
  "projects.constraints.*.allowedProviderHosts": { type: "string[]", description: "Computers on the local network (host names or IP addresses, no port) that a local provider allowed by id (`llama-server`, or an `openai-compatible` / `qwen-openai-compatible` entry not marked `modelMode: \"cloud\"`) may be reached at.", optional: true },
  "tools.shell.defaultTimeoutMs": { type: "number", description: "Wall-clock wait, in milliseconds, for an `os.shell.run` call whose `timeoutMs` the model omitted. Default 600 000 (10 min). A command still running then is not killed: it is detached as a job the model can `wait` for or `kill`, with its output so far in the result. `0` = no default, which is the pre-v67 behaviour." },
  "tools.shell.jobMaxMs": { type: "number", description: "Absolute ceiling, in milliseconds, for a detached job, counted from its start — kept or not, waited on or not. Default 3 600 000 (1 h). A positive integer." },
